:root {
  --card-bg: #ffffff;
  --card-border: #c9e8f0;
  --card-radius: 16px;

  --header-bg: #e0f4fa;
  --tank-name-color: #0e4f6b;
  --tank-type-color: #5a8fa0;

  --badge-bg: #1a9e6e;
  --badge-text: #ffffff;

  --param-label-color: #6a8f9a;
  --param-value-color: #0e4f6b;
  --param-unit-color: #8ab5c4;
  --bar-track: #dff0f5;

  --fill-temp: #f4a35a;
  --fill-ph: #4db8d4;
  --fill-sal: #6c8ef5;
  --fill-nit: #e06b6b;

  --section-title-color: #0e4f6b;

  --fish-tag-bg: #dff0f5;
  --fish-tag-text: #1a6a80;
  --coral-tag-bg: #fde9d5;
  --coral-tag-text: #a0522d;

  --footer-bg: #f4fbfd;
  --footer-label: #8ab5c4;
  --footer-val: #0e4f6b;
  --footer-good: #1a9e6e;
  --divider: #d0eaf2;
}

.tank-card {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: var(--card-radius);
  width: 500px;
  overflow: hidden;
}

.card-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.tank-icon {
  font-size: 28px;
  line-height: 1;
}

.tank-name {
  font-size: 16px;
  font-weight: 700;
  color: var(--tank-name-color);
  line-height: 1.2;
}

.tank-type {
  font-size: 12px;
  color: var(--tank-type-color);
  margin-top: 2px;
}

.status-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 12px;
  font-weight: 700;
  padding: 4px 12px;
  border-radius: 20px;
}

.params-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  border-bottom: 1px solid var(--divider);
}

.param-item {
  padding: 14px 12px 10px;
  border-right: 1px solid var(--divider);
}

.param-item:last-child {
  border-right: none;
}

.param-label {
  font-size: 11px;
  color: var(--param-label-color);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 4px;
}

.param-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--param-value-color);
  line-height: 1.1;
}

.param-unit {
  font-size: 11px;
  font-weight: 400;
  color: var(--param-unit-color);
  margin-left: 1px;
}

.param-bar {
  height: 4px;
  background: var(--bar-track);
  border-radius: 2px;
  margin-top: 8px;
  overflow: hidden;
}

.param-fill {
  height: 100%;
  border-radius: 2px;
}

.fill-temp { background: var(--fill-temp); width: 72%; }
.fill-ph   { background: var(--fill-ph);   width: 82%; }
.fill-sal  { background: var(--fill-sal);  width: 70%; }
.fill-nit  { background: var(--fill-nit);  width: 40%; }

.inhabitants-section {
  padding: 12px 18px;
  border-bottom: 1px solid var(--divider);
}

.section-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--section-title-color);
  margin-bottom: 8px;
}

.inhabitants-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.fish-tag {
  background: var(--fish-tag-bg);
  color: var(--fish-tag-text);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
}

.coral-tag {
  background: var(--coral-tag-bg);
  color: var(--coral-tag-text);
}

.card-footer {
  display: flex;
  background: var(--footer-bg);
  padding: 10px 18px;
  gap: 0;
}

.footer-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  border-right: 1px solid var(--divider);
  padding-right: 14px;
  padding-left: 14px;
}

.footer-item:first-child {
  padding-left: 0;
}

.footer-item:last-child {
  border-right: none;
}

.footer-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--footer-label);
}

.footer-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--footer-val);
}

.footer-val.good {
  color: var(--footer-good);
}
